      e.directory === directory && e.exposure === exposure && e.severities.includes(severity) &&
      (e.package === undefined || e.package === name)
    ));
    const active = matching.find(e => e.reviewBy >= today);
    if (active) {
      if (FAILING.has(severity) && active.package === undefined) {
